/**
 * The sign-on artwork: the three panels from the Postboi connecting dialog, one per step.
 *
 * Cropped from the source mock with their drawn borders trimmed off — the dialog draws its
 * own frame, and leaving theirs in showed as a seam where the two purples met. Resized to
 * the size they render at and palettised, since flat cartoon art quantises to a fraction of
 * the bytes with nothing visible lost.
 *
 * Base64 for the same reason as the sounds: neither svelte-package nor the CLI's bun build
 * is guaranteed to carry a binary asset through to dist.
 */

/** PNG bytes by step name, base64. Served at `/__postboi/api/art/:name`. */
export const ART: Record<string, string> = {
	locating:
		"",
	connecting:
		"",
	intercepting:
		"",
}
